// ===== INICIALIZAÇÃO INFALÍVEL =====
function runInitSafely() {
  if (window._appInitialized) return;
  window._appInitialized = true;
  initApp();
}

if (document.readyState === 'complete' || document.readyState === 'interactive') {
  setTimeout(runInitSafely, 0);
} else {
  document.addEventListener('DOMContentLoaded', runInitSafely);
}
window.addEventListener('load', runInitSafely);
setTimeout(runInitSafely, 100);

// A tela nunca era atualizada quando dado novo chegava da nuvem em segundo
// plano (ex: import de escala feito em outro aparelho) — o CloudStore já
// disparava esse evento, mas nada escutava, então só um F5 manual mostrava
// os dados novos (achado de 20/08/2026).
window.addEventListener('jr-cloud-sync', () => {
  // Achado de 21/08/2026: renderApp() redesenha a TELA INTEIRA do zero. Se
  // essa sincronização em segundo plano (roda a cada ~30s, sem o usuário
  // pedir) chegasse enquanto alguém estava no meio de preencher um
  // formulário (ex: Abertura de Devolução SAC), o formulário inteiro era
  // apagado sem aviso nenhum — tudo que a pessoa tinha digitado se perdia.
  // Se o foco estiver num campo editável agora, adia o redesenho: os dados
  // novos já estão salvos em memória (isso já aconteceu antes deste
  // evento disparar), só a TELA não é redesenhada ainda — ela pega os
  // dados atualizados normalmente na próxima renderização (ex: ao enviar
  // o formulário, fechar um modal, trocar de aba).
  //
  // 28/08/2026 — O FOCO SOZINHO DEIXOU DE BASTAR. A partir desta versão a
  // sincronização também dispara quando a pessoa VOLTA para a tela (ver
  // "SINCRONIZA AO VOLTAR PARA A TELA" no fim do cloudStore.js), e é
  // justamente aí que o formulário tende a estar preenchido SEM foco em
  // nada: no celular se toca fora do campo para fechar o teclado antes de
  // trocar de app, e ao voltar o activeElement é o <body>. Com o teste
  // antigo, esse era o caminho para o redesenho apagar o que já estava
  // digitado. Por isso vale também a MARCA de digitação, acesa pelo
  // listener logo abaixo e apagada em todo renderApp().
  const emCampoEditavel = document.activeElement && document.activeElement.matches &&
    document.activeElement.matches('input, textarea, select');
  if (emCampoEditavel || window._jrTelaComDigitacao) {
    if (typeof showToast === 'function') {
      showToast('🔄 Novos dados chegaram da nuvem. A tela atualiza sozinha assim que você terminar aqui.', 'warning');
    }
    return;
  }
  if (typeof renderApp === 'function') renderApp();
});

// Acende a marca de "tem coisa digitada nesta tela ainda não salva". Só vale
// para o #main-content: o que está em #modal-container não corre risco,
// porque renderApp() troca apenas o #main-content e não encosta no modal.
// Na fase de captura para pegar o evento mesmo em campo que interrompe a
// propagação.
document.addEventListener('input', (ev) => {
  const alvo = ev.target;
  if (alvo && alvo.closest && alvo.closest('#main-content')) {
    window._jrTelaComDigitacao = true;
  }
}, true);

// ===== UTILITÁRIOS GLOBAIS DE FORMATAÇÃO E NORMALIZAÇÃO DE DATA (DD/MM/AAAA) =====
function formatarData(val, fallback = '—') {
  if (val === null || val === undefined || val === '') return fallback;
  
  if (val instanceof Date) {
    if (isNaN(val.getTime())) return fallback;
    const d = String(val.getDate()).padStart(2, '0');
    const m = String(val.getMonth() + 1).padStart(2, '0');
    const y = val.getFullYear();
    return `${d}/${m}/${y}`;
  }

  // Serial Excel (número ex: 45518)
  if (typeof val === 'number' || (typeof val === 'string' && /^\d{5}(\.\d+)?$/.test(val.trim()))) {
    const num = Number(val);
    if (num > 20000 && num < 60000) {
      const date = new Date(Math.round((num - 25569) * 86400 * 1000));
      if (!isNaN(date.getTime())) {
        const d = String(date.getUTCDate()).padStart(2, '0');
        const m = String(date.getUTCMonth() + 1).padStart(2, '0');
        const y = date.getUTCFullYear();
        return `${d}/${m}/${y}`;
      }
    }
  }

  let s = String(val).trim();
  if (!s || s === '-' || s === '—' || s === 'null' || s === 'undefined' || s === 'NaN') return fallback;

  // Se já estiver no formato DD/MM/AAAA ou DD/MM/AAAA HH:mm...
  const matchBr = s.match(/^(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{2,4})/);
  if (matchBr && (Number(matchBr[1]) > 12 || matchBr[0].includes('/'))) {
    const d = matchBr[1].padStart(2, '0');
    const m = matchBr[2].padStart(2, '0');
    let y = matchBr[3];
    if (y.length === 2) y = '20' + y;
    return `${d}/${m}/${y}`;
  }

  // Se estiver no formato YYYY-MM-DD ou YYYY-MM-DDTHH:mm:ss... ou YYYY/MM/DD
  const matchIso = s.match(/^(\d{4})[\/\-\.](\d{1,2})[\/\-\.](\d{1,2})/);
  if (matchIso) {
    const y = matchIso[1];
    const m = matchIso[2].padStart(2, '0');
    const d = matchIso[3].padStart(2, '0');
    return `${d}/${m}/${y}`;
  }

  // Qualquer outro formato que Date.parse reconheça
  const parsed = new Date(s);
  if (!isNaN(parsed.getTime())) {
    const d = String(parsed.getDate()).padStart(2, '0');
    const m = String(parsed.getMonth() + 1).padStart(2, '0');
    const y = parsed.getFullYear();
    return `${d}/${m}/${y}`;
  }

  return s;
}

function formatarDataHora(val, fallback = '—') {
  if (val === null || val === undefined || val === '') return fallback;
  const dataFmt = formatarData(val, '');
  if (!dataFmt) return fallback;
  
  let horaFmt = '';
  if (val instanceof Date && !isNaN(val.getTime())) {
    horaFmt = val.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
  } else {
    const s = String(val).trim();
    if (s.includes('T') || s.includes(':')) {
      const parsed = new Date(s);
      if (!isNaN(parsed.getTime())) {
        horaFmt = parsed.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
      }
    }
  }
  return horaFmt ? `${dataFmt} ${horaFmt}` : dataFmt;
}

function normalizarDataImportacao(val, fallbackData = '') {
  if (val === null || val === undefined || val === '') {
    return fallbackData ? formatarData(fallbackData, '') : '';
  }
  const fmt = formatarData(val, '');
  if (fmt && fmt !== '—' && fmt !== '-') return fmt;
  return fallbackData ? formatarData(fallbackData, '') : String(val).trim();
}

window.formatarData = formatarData;
window.formatarDataHora = formatarDataHora;
window.normalizarDataImportacao = normalizarDataImportacao;

function initApp() {
  try {
    initTheme();
    updateUserHeader();
    renderApp();
    setupPwa();
  } catch (err) {
    console.error("Erro na inicialização do app:", err);
    try {
      if (typeof db !== 'undefined' && typeof INITIAL_DATA !== 'undefined') {
        db.data = JSON.parse(JSON.stringify(INITIAL_DATA));
        if (typeof db.init === 'function') db.init();
      }
      updateUserHeader();
      renderApp();
    } catch(e2) {
      console.error("Erro crítico ao renderizar:", e2);
    }
  }
}

// ===== TEMA CLARO / ESCURO (SOL / LUA) =====
function initTheme() {
  let currentTheme = 'dark';
  try {
    currentTheme = localStorage.getItem('jr_sac_theme') || 'dark';
  } catch(e) {
    currentTheme = 'dark';
  }
  applyTheme(currentTheme);
}

function applyTheme(theme) {
  const html = document.documentElement;
  const body = document.body;
  const icon = document.getElementById('theme-icon');
  
  if (theme === 'light') {
    if (html && html.classList) {
      html.classList.remove('dark');
      html.classList.add('light');
    }
    if (body && body.classList) {
      body.classList.remove('bg-slate-950', 'text-slate-100');
      body.classList.add('bg-slate-100', 'text-slate-900');
    }
    if (icon) icon.textContent = '🌙';
  } else {
    if (html && html.classList) {
      html.classList.remove('light');
      html.classList.add('dark');
    }
    if (body && body.classList) {
      body.classList.remove('bg-slate-100', 'text-slate-900');
      body.classList.add('bg-slate-950', 'text-slate-100');
    }
    if (icon) icon.textContent = '☀️';
  }
  try {
    localStorage.setItem('jr_sac_theme', theme);
  } catch(e) {
    console.warn("Nao foi possivel salvar tema no localStorage:", e);
  }
}

function toggleTheme() {
  let currentTheme = 'dark';
  try {
    currentTheme = localStorage.getItem('jr_sac_theme') || 'dark';
  } catch(e) {
    currentTheme = 'dark';
  }
  const newTheme = currentTheme === 'dark' ? 'light' : 'dark';
  applyTheme(newTheme);
}

function setupPwa() {
  let deferredPrompt;
  const pwaBtn = document.getElementById('btn-pwa-install');
  if (typeof window !== 'undefined' && typeof window.addEventListener === 'function') {
    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault(); deferredPrompt = e;
      if (pwaBtn && pwaBtn.classList) pwaBtn.classList.remove('hidden');
    });
  }
  if (pwaBtn && typeof pwaBtn.addEventListener === 'function') {
    pwaBtn.addEventListener('click', async () => {
      if (deferredPrompt) {
        deferredPrompt.prompt();
        const { outcome } = await deferredPrompt.userChoice;
        if (outcome === 'accepted' && pwaBtn.classList) pwaBtn.classList.add('hidden');
        deferredPrompt = null;
      } else {
        alert('Para instalar no Android ou Windows: Clique nos três pontos do navegador → "Instalar JR SAC".');
      }
    });
  }
  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.getRegistrations().then(registrations => {
      for (let r of registrations) r.unregister();
    }).catch(() => {});
  }
}

