// ===== TOAST NOTIFICATION HELPER =====
function showToast(message, type = 'success') {
  const existing = document.getElementById('jr-toast-notification');
  if (existing) existing.remove();

  const toast = document.createElement('div');
  toast.id = 'jr-toast-notification';
  const bgColor = type === 'success' ? 'bg-emerald-600' : (type === 'error' ? 'bg-red-600' : 'bg-amber-600');
  toast.className = `fixed bottom-5 right-5 z-50 ${bgColor} text-white font-extrabold px-5 py-3 rounded-xl shadow-2xl flex items-center gap-3 transition-all duration-300 transform translate-y-2 opacity-0 text-xs`;
  toast.innerHTML = `<span>${type === 'success' ? '✅' : '⚠️'}</span> <span>${message}</span>`;

  document.body.appendChild(toast);
  setTimeout(() => {
    toast.classList.remove('translate-y-2', 'opacity-0');
  }, 50);

  setTimeout(() => {
    toast.classList.add('translate-y-2', 'opacity-0');
    setTimeout(() => toast.remove(), 300);
  }, 4000);
}

// Painel de acompanhamento de uso do armazenamento local (item 0.1 da
// auditoria de 17/08/2026) — complementa a correção estrutural (separação
// de clientes/produtos em chave própria), servindo para a equipe acompanhar
// o crescimento dos dados operacionais ao longo do tempo.
function renderStorageUsagePanel() {
  if (!db || typeof db.getStorageUsageInfo !== 'function') return '';
  const info = db.getStorageUsageInfo();
  const corMap = {
    green: { bg: 'bg-emerald-950/30', border: 'border-emerald-900/60', text: 'text-emerald-400', bar: 'bg-emerald-500' },
    amber: { bg: 'bg-amber-950/30', border: 'border-amber-900/60', text: 'text-amber-400', bar: 'bg-amber-500' },
    red:   { bg: 'bg-red-950/30', border: 'border-red-900/60', text: 'text-red-400', bar: 'bg-red-500' }
  };
  const cor = corMap[info.nivel] || corMap.green;
  const mensagem = info.nivel === 'red'
    ? 'Uso elevado — risco de falha ao salvar dados neste dispositivo. Considere liberar espaço.'
    : (info.nivel === 'amber' ? 'Uso moderado — acompanhe o crescimento dos dados.' : 'Uso normal.');

  return `
    <div class="${cor.bg} border ${cor.border} p-5 rounded-2xl text-xs shadow-2xl">
      <div class="flex flex-col md:flex-row md:items-center justify-between gap-3 mb-3">
        <div class="font-bold ${cor.text} text-sm flex items-center gap-2">
          <span>💾</span> Uso do Armazenamento Local (Dados Operacionais)
        </div>
        <span class="text-slate-400">${info.operacionalKB} KB usados de ~5.120 KB estimados (${info.percentual}%)</span>
      </div>
      <div class="w-full bg-slate-800 rounded-full h-2 overflow-hidden mb-2">
        <div class="${cor.bar} h-2 rounded-full transition-all" style="width:${Math.min(info.percentual, 100)}%"></div>
      </div>
      <p class="text-slate-400 leading-relaxed">${mensagem} O catálogo de clientes e produtos (~${info.estaticoKB} KB) fica em um armazenamento separado e não conta para este limite.</p>
      ${renderFilaFotosPanel()}
    </div>`;
}

// Fila de fotos (v5.1.0). Fica dentro do painel de armazenamento porque é
// exatamente a pergunta que o painel responde — "o que este aparelho está
// segurando?" — só que para o que NÃO está no localStorage.
//
// Lê window._fotosNaFila, alimentado por atualizarTarjaFotosPendentes(): o
// IndexedDB só responde por Promise e este render é síncrono. O valor pode
// ficar um ciclo atrasado; a tarja do topo é a fonte imediata.
function renderFilaFotosPanel() {
  if (!window.fotoStore || !window.fotoStore.disponivel()) return '';
  if (typeof window.atualizarTarjaFotosPendentes === 'function') window.atualizarTarjaFotosPendentes();
  const n = window._fotosNaFila || 0;
  if (!n) {
    return `<p class="text-slate-500 mt-2 pt-2 border-t border-slate-800/80 leading-relaxed">
      📷 Nenhuma foto pendente. As fotos da custódia de reentrega ficam no servidor, não neste aparelho.
    </p>`;
  }
  return `<div class="mt-2 pt-2 border-t border-amber-800/60 text-amber-300 leading-relaxed">
      <strong>📷 ${n} foto(s) aguardando envio.</strong>
      Estão guardadas neste aparelho (IndexedDB, fora do limite acima) e sobem sozinhas quando houver rede.
      <strong>Não limpe os dados do navegador enquanto este número não for zero</strong> — a foto se perde.
      <button onclick="jrSubirFotosAgora()" class="ml-1 bg-amber-700 hover:bg-amber-600 text-white font-bold px-2 py-0.5 rounded text-[10px]">Tentar enviar agora</button>
    </div>`;
}

// =============================================================================
// PORTÃO DA ÁREA ADMINISTRATIVA (26/08/2026)
//
// O menu mostra as quatro telas administrativas para TODO MUNDO de propósito
// (`papeis: null` em NAV_GRUPOS): quem protege elas é a senha de admin, não o
// papel do usuário. Só que a senha era cobrada em UMA delas — "Logins e
// Senhas", pela trava `window._gestaoUsuariosDesbloqueado`. Cadastros
// Mestres, Governança & Lixeira e Conector Power BI abriam direto para
// qualquer pessoa logada: dava para apagar cadastro mestre, restaurar item da
// lixeira e baixar o JSON inteiro do banco sem senha nenhuma.
//
// Agora as quatro dividem a MESMA tranca de sessão: desbloqueou uma,
// desbloqueou a área; handleLogout() tranca tudo de novo. A tranca vive só em
// memória — F5 fecha a porta, que é o comportamento desejado.
// =============================================================================
function areaAdminDesbloqueada() {
  return window._areaAdminDesbloqueada === true;
}

function renderPortaoAdmin(titulo, descricao) {
  return `
    <div class="max-w-md mx-auto mt-16 text-center space-y-4">
      <div class="text-5xl">🔒</div>
      <h2 class="text-lg font-black text-white">${titulo || 'Área Administrativa'}</h2>
      <p class="text-sm text-slate-400 leading-relaxed">${descricao || 'Esta área requer autorização do administrador.'}</p>
      <button onclick="desbloquearAreaAdmin()" class="bg-red-700 hover:bg-red-600 text-white font-bold px-5 py-2.5 rounded-xl text-sm shadow inline-flex items-center gap-2 transition">
        🔑 Desbloquear com Senha Admin
      </button>
      <p class="text-[11px] text-slate-500">Vale para as quatro telas de Administração até você sair do sistema.</p>
    </div>`;
}

function desbloquearAreaAdmin() {
  abrirModalConfirmacaoAdmin({
    titulo: 'Acesso à Área Administrativa',
    mensagem: 'Informe a senha de administrador para abrir Cadastros Mestres, Logins e Senhas, Governança &amp; Lixeira e o Conector Power BI.',
    onConfirm: (pwd) => {
      // .trim() para casar com o que o store faz nas próprias conferências
      // (resetGlobalTreinamento, expurgo): espaço colado no fim da senha não
      // pode virar "senha incorreta".
      if (String(pwd).trim() !== db.getAdminPassword()) {
        alert('❌ Senha de administrador incorreta.');
        return;
      }
      window._areaAdminDesbloqueada = true;
      renderApp();
    }
  });
}

function bloquearAreaAdmin() {
  window._areaAdminDesbloqueada = false;
  renderApp();
}

// Botão "Bloquear novamente", igual nas quatro telas administrativas.
function botaoBloquearAreaAdmin() {
  return `<button onclick="bloquearAreaAdmin()" class="bg-slate-800 hover:bg-slate-700 text-slate-300 font-bold px-3 py-1.5 rounded-lg text-xs transition shrink-0" title="Tranca as quatro telas de Administração">🔒 Bloquear novamente</button>`;
}

