// PRIORIDADE 7d: janela de retenção configurável (dias) da Lixeira antes do
// expurgo definitivo ficar "elegível" — hoje o expurgo continua manual
// (item a item, pelo admin), isto só calcula/exibe a contagem regressiva.
const JANELA_RETENCAO_LIXEIRA_DIAS = 30;

function diasParaExpurgo(deletedAt) {
  if (!deletedAt) return null;
  const deletadoEm = new Date(deletedAt).getTime();
  if (isNaN(deletadoEm)) return null;
  const diasDecorridos = (Date.now() - deletadoEm) / (1000 * 60 * 60 * 24);
  return Math.ceil(JANELA_RETENCAO_LIXEIRA_DIAS - diasDecorridos);
}

