    "ENDEREÇO NÃO LOCALIZADO",
    "ESTABELECIMENTO FECHADO",
    "CLIENTE AUSENTE",
    "FALTA DE TEMPO HÁBIL",
    "MERCADORIA AVARIADA",
    "DIVERGÊNCIA DE NOTA",
    "OUTROS"
