function handleCadColaboradorCDSubmit(e) {
  e.preventDefault();
  const chapa = document.getElementById('cad-colab-chapa')?.value || '';
  const nome = document.getElementById('cad-colab-nome')?.value || '';
  const cpf = document.getElementById('cad-colab-cpf')?.value || '';
  const funcao = document.getElementById('cad-colab-funcao')?.value || 'SEPARADOR';
  const secao = document.getElementById('cad-colab-secao')?.value || '';
  const dataAdmissao = document.getElementById('cad-colab-admissao')?.value || '';
  const dataDesligamento = document.getElementById('cad-colab-desligamento')?.value || '';

  if (!nome.trim()) { alert('Informe o nome do colaborador!'); return; }

  db.saveColaboradorCD({
    chapa: chapa.trim(),
    nome: nome.trim(),
    cpf: cpf.trim(),
    funcao: funcao.trim(),
    secao: secao.trim(),
    data_admissao: dataAdmissao || null,
    data_desligamento: dataDesligamento || null,
    ativo: true
  });

  showToast(`✅ Colaborador "${nome.toUpperCase().trim()}" cadastrado com sucesso!`);
  renderApp();
}

function abrirModalEditarColaboradorCD(id) {
  const colabs = db.getColaboradoresCD();
  const item = colabs.find(c => c.id == id);
  if (!item) return;

  const funcoesDisponiveis = [
    "SEPARADOR",
    "CONFERENTE",
    "OPERADOR DE EMPILHADEIRA",
    "AUXILIAR JUNIOR",
    "MOVIMENTADOR DE MERCADORIA",
    "OPERADOR DE PICKING",
    "SUPERVISOR DE OPERACOES",
    "ASSISTENTE OPERACIONAL DE LOGISTICA",
    "GERENTE DE CD"
  ];

  const secoesDisponiveis = [
    "CARREGAMENTO FRIOS - 1 TURNO",
    "CARREGAMENTO FRIOS - 2 TURNO",
    "CARREGAMENTO FRIOS - 3 TURNO",
    "CARREGAMENTO SECOS",
    "CARREGAMENTO"
  ];

  const container = document.getElementById('modal-container');
  if (!container) return;

  container.innerHTML = `
    <div class="bg-slate-900 border border-slate-700 rounded-xl p-5 max-w-lg w-full shadow-2xl text-white space-y-4">
      <div class="flex items-center justify-between border-b border-slate-800 pb-3">
        <h3 class="text-sm font-bold text-emerald-400 uppercase flex items-center gap-2">
          <span>✏️</span> Editar Colaborador do CD
        </h3>
        <button onclick="fecharModalResumo()" class="text-slate-400 hover:text-white font-bold">✕</button>
      </div>

      <form onsubmit="handleSalvarEdicaoColaboradorCD(event, ${item.id})" class="space-y-3 text-xs">
        <div class="grid grid-cols-2 gap-3">
          <div>
            <label class="block text-[10px] text-slate-400 mb-1 font-bold">Nº Chapa</label>
            <input type="text" id="ed-colab-chapa" value="${item.chapa||''}" class="w-full bg-slate-800 border border-slate-700 text-emerald-400 font-bold rounded p-2 text-xs" oninput="forcarMaiuscula(this)">
          </div>
          <div>
            <label class="block text-[10px] text-slate-400 mb-1 font-bold">CPF</label>
            <input type="text" id="ed-colab-cpf" value="${item.cpf||''}" class="w-full bg-slate-800 border border-slate-700 text-white rounded p-2 text-xs" oninput="forcarMaiuscula(this)">
          </div>
        </div>

        <div>
          <label class="block text-[10px] text-slate-400 mb-1 font-bold">Nome Completo *</label>
          <input type="text" id="ed-colab-nome" required value="${item.nome||''}" class="w-full bg-slate-800 border border-slate-700 text-white rounded p-2 text-xs uppercase font-bold" oninput="forcarMaiuscula(this)">
        </div>

        <div class="grid grid-cols-2 gap-3">
          <div>
            <label class="block text-[10px] text-slate-400 mb-1 font-bold">Função *</label>
            <select id="ed-colab-funcao" required class="w-full bg-slate-800 border border-slate-700 text-amber-300 font-bold rounded p-2 text-xs">
              ${funcoesDisponiveis.map(f => `<option value="${f}" ${item.funcao===f?'selected':''}>${f}</option>`).join('')}
            </select>
          </div>
          <div>
            <label class="block text-[10px] text-slate-400 mb-1 font-bold">Seção / Turno</label>
            <select id="ed-colab-secao" class="w-full bg-slate-800 border border-slate-700 text-white rounded p-2 text-xs">
              ${secoesDisponiveis.map(s => `<option value="${s}" ${item.secao===s?'selected':''}>${s}</option>`).join('')}
            </select>
          </div>
        </div>

        <div>
          <label class="block text-[10px] text-slate-400 mb-1 font-bold">Situação / Status</label>
          <select id="ed-colab-ativo" class="w-full bg-slate-800 border border-slate-700 text-white rounded p-2 text-xs font-bold">
            <option value="sim" ${item.ativo!==false?'selected':''}>🟢 Ativo na Operação</option>
            <option value="nao" ${item.ativo===false?'selected':''}>🔴 Inativo / Desativado</option>
          </select>
        </div>

        <div class="flex items-center justify-end gap-2 pt-3 border-t border-slate-800">
          <button type="button" onclick="fecharModalResumo()" class="bg-slate-800 hover:bg-slate-700 text-slate-300 font-bold px-3 py-1.5 rounded text-xs">Cancelar</button>
          <button type="submit" class="bg-emerald-600 hover:bg-emerald-500 text-white font-bold px-4 py-1.5 rounded text-xs shadow">Salvar Alterações</button>
        </div>
      </form>
    </div>
  `;
  container.classList.remove('hidden');
}

function handleSalvarEdicaoColaboradorCD(e, id) {
  e.preventDefault();
  const chapa = document.getElementById('ed-colab-chapa')?.value || '';
  const nome = document.getElementById('ed-colab-nome')?.value || '';
  const cpf = document.getElementById('ed-colab-cpf')?.value || '';
  const funcao = document.getElementById('ed-colab-funcao')?.value || 'SEPARADOR';
  const secao = document.getElementById('ed-colab-secao')?.value || '';
  const ativo = document.getElementById('ed-colab-ativo')?.value === 'sim';

  db.saveColaboradorCD({
    id: id,
    chapa: chapa.trim(),
    nome: nome.trim(),
    cpf: cpf.trim(),
    funcao: funcao.trim(),
    secao: secao.trim(),
    ativo: ativo
  });

  fecharModalResumo();
  showToast('✅ Cadastro do colaborador atualizado!');
  renderApp();
}

function deletarColaboradorCD(id, nome) {
  if (!confirm(`Excluir o colaborador "${nome}" do cadastro do CD?`)) return;
  db.deleteColaboradorCD(id);
  showToast('🗑️ Colaborador excluído com sucesso.');
  renderApp();
}

function handleCadSeparadorSubmit(e) {
  e.preventDefault();
  const nome = document.getElementById('cad-sep-nome').value.toUpperCase().trim();
  if (!nome) return;
  db.saveColaboradorCD({ nome: nome, funcao: 'SEPARADOR' });
  alert(`✅ "${nome}" cadastrado com sucesso!`);
  renderApp();
}

function deleteSeparador(nome) {
  if (!confirm(`Excluir "${nome}" da lista de Separadores/Conferentes?`)) return;
  const item = (db.getColaboradoresCD() || []).find(c => c.nome === nome);
  if (item) {
    db.deleteColaboradorCD(item.id);
  }
  renderApp();
}


