// ─────────────────────────────────────────────────────────────────────────────
// 3D — PAINEL "LIBERADOS"
// ─────────────────────────────────────────────────────────────────────────────
function renderPainelLiberados(retencoes) {
  const liberados = retencoes.filter(r => r.status === 'LIBERADO')
    .sort((a, b) => new Date(b.data_liberacao) - new Date(a.data_liberacao));

  const calcImobilizacao = (inicioStr, fimStr) => {
    if (!inicioStr || !fimStr) return { dias: '—', hhmmss: '—', cls: 'text-slate-500' };
    const dtI = new Date(inicioStr.includes('T') ? inicioStr : inicioStr + 'T08:00:00');
    const dtF = new Date(fimStr.includes('T') ? fimStr : fimStr + 'T18:00:00');
    const diffMs = Math.max(0, dtF.getTime() - dtI.getTime());
    const dias = Math.round(diffMs / 86400000);
    const hhmmss = formatarDuracaoHHMMSS(diffMs, 'ms');
    const cls = dias <= 1 ? 'text-emerald-400' : (dias <= 3 ? 'text-amber-400' : 'text-red-400');
    return { dias, hhmmss, cls };
  };

  const linhas = liberados.length === 0
    ? `<tr><td colspan="12" class="p-8 text-center text-slate-500 text-xs">Nenhum veículo liberado ainda.</td></tr>`
    : liberados.map((r, i) => {
        const imob = calcImobilizacao(r.data_parada || r.criado_em, r.data_liberacao);
        return `
        <tr class="hover:bg-slate-800/40 transition">
          <td class="p-2 text-center text-slate-400 text-xs font-bold">${i + 1}</td>
          <td class="p-2 font-black text-white text-xs tracking-wide">${r.placa || '—'}</td>
          <td class="p-2">
            <span class="px-2 py-0.5 rounded-full text-[10px] font-extrabold
              ${r.tipo_os === 'SINISTRO' ? 'bg-red-900/60 text-red-300' :
                r.tipo_os === 'PREVENTIVA' ? 'bg-blue-900/60 text-blue-300' :
                'bg-amber-900/60 text-amber-300'}">
              ${r.tipo_os || '—'}
            </span>
          </td>
          <td class="p-2 text-slate-300 text-xs max-w-[160px]">
            <div class="truncate" title="${(r.motivo||'').replace(/"/g,'&quot;')}">${r.motivo || '—'}</div>
          </td>
          <td class="p-2 text-slate-400 text-xs font-mono">${r.numero_retencao || '—'}</td>
          <td class="p-2 text-sky-300 text-xs font-mono">${renderNumeroOsLink(r.numero_os, r.link_os)}</td>
          <td class="p-2 text-slate-400 text-xs">${r.local || '—'}</td>
          <td class="p-2 text-slate-400 text-xs">${formatarData(r.data_parada)}</td>
          <td class="p-2 text-emerald-400 text-xs font-bold">${formatarData(r.data_liberacao)}</td>
          <td class="p-2 text-slate-300 text-xs max-w-[180px]">
            <div class="truncate" title="${(r.descricao_acao_liberacao||'').replace(/"/g,'&quot;')}">${r.descricao_acao_liberacao || '—'}</div>
          </td>
          <td class="p-2 text-center font-mono font-bold text-xs ${imob.cls}">${imob.hhmmss} <span class="text-[10px] text-slate-500">(${imob.dias}d)</span></td>
          <td class="p-2 text-center">
            <button onclick="abrirModalEdicaoFrota(${r.id})"
              class="bg-sky-700 hover:bg-sky-600 active:scale-95 text-white text-[10px] font-bold px-2 py-1 rounded-lg transition flex items-center gap-1 justify-center mx-auto">
              ✏️
            </button>
          </td>
        </tr>`;
      }).join('');

  return `
    <div class="bg-slate-900 border border-slate-800 rounded-xl overflow-hidden shadow-lg">
      <!-- Cabeçalho -->
      <div class="flex items-center justify-between px-4 py-3 border-b border-slate-800">
        <div class="flex items-center gap-2">
          <span class="text-sm font-black text-emerald-400">✅ Veículos Liberados da Oficina</span>
          <span class="bg-emerald-500 text-white text-[10px] font-black px-2 py-0.5 rounded-full">${liberados.length}</span>
        </div>
        <button onclick="emitirRelatorioFrota('liberados')"
          class="bg-slate-800 hover:bg-slate-700 active:scale-95 text-slate-300 hover:text-white text-xs font-bold px-3 py-1.5 rounded-lg transition flex items-center gap-2">
          📄 Emitir Relatório
        </button>
      </div>
      <!-- Tabela -->
      <div class="overflow-x-auto">
        <table class="w-full text-xs">
          <thead>
            <tr class="bg-slate-950 text-slate-500 uppercase text-[10px] tracking-wider">
              <th class="p-2 text-center">QNT</th>
              <th class="p-2 text-left">PLACA</th>
              <th class="p-2 text-left">TIPO OS</th>
              <th class="p-2 text-left">MOTIVO</th>
              <th class="p-2 text-left">RET</th>
              <th class="p-2 text-left">N° OS</th>
              <th class="p-2 text-left">LOCAL</th>
              <th class="p-2 text-left">PARADO EM</th>
              <th class="p-2 text-left">LIBERADO EM</th>
              <th class="p-2 text-left">AÇÃO REALIZADA</th>
              <th class="p-2 text-center">TEMPO IMOBILIZADO</th>
              <th class="p-2 text-center">AÇÕES</th>
            </tr>
          </thead>
          <tbody class="divide-y divide-slate-800/60">
            ${linhas}
          </tbody>
        </table>
      </div>
    </div>`;
}

// ─────────────────────────────────────────────────────────────────────────────
// FUNÇÕES DE AÇÃO — FROTA
// ─────────────────────────────────────────────────────────────────────────────

/** 3B-action: Salva nova retenção a partir do formulário. */
async function salvarRetencaoFrota(event) {
  event.preventDefault();
  const veiculoId  = document.getElementById('frt-veiculo-id')?.value;
  const placa      = document.getElementById('frt-placa-hidden')?.value;
  const tipoVeic   = document.getElementById('frt-tipo-hidden')?.value;
  const dataParada = document.getElementById('frt-data-parada')?.value;
  const motivo     = document.getElementById('frt-motivo')?.value?.trim();
  const tipoOs     = document.getElementById('frt-tipo-os')?.value;
  const local      = document.getElementById('frt-local')?.value?.trim();
  const dataPrev   = document.getElementById('frt-data-previsao')?.value;
  const linkOsRaw  = normalizarCaseLinkOs(document.getElementById('frt-link-os')?.value?.trim());

  if (!veiculoId || !placa) { alert('⚠️ Selecione um veículo da lista de sugestões.'); return; }
  if (!dataParada) { alert('⚠️ Informe a data de parada.'); return; }
  if (!motivo)    { alert('⚠️ Informe o motivo.'); return; }
  if (linkOsRaw && !/^https?:\/\/.+/i.test(linkOsRaw)) {
    alert('⚠️ O link do sistema de OS deve começar com http:// ou https://');
    document.getElementById('frt-link-os')?.focus();
    return;
  }

  // O Nº OS não é mais digitado manualmente — é derivado automaticamente
  // do link informado (ver extrairIdentificadorOsDoLink), já que clicar
  // no link já leva direto à OS correta na outra plataforma.
  const numeroOs = extrairIdentificadorOsDoLink(linkOsRaw);

  // Mesma causa raiz do fix de importação de escala (21/08/2026): o número
  // sequencial de retenção é gerado olhando só o estado LOCAL deste
  // aparelho. Sem puxar a nuvem antes, dois aparelhos desincronizados
  // podem gerar o MESMO número para retenções diferentes — e a coluna é
  // UNIQUE no banco, então uma delas nunca sincroniza (silenciosamente).
  if (window.cloudStore && window.cloudStore.isConfigured()) {
    try { await window.cloudStore.syncCloudToLocal(); } catch(errSync) {}
  }

  const result = db.addRetencaoFrota({
    veiculo_id:    veiculoId,
    placa:         placa,
    tipo_veiculo:  tipoVeic,
    data_parada:   dataParada,
    motivo:        motivo,
    tipo_os:       tipoOs,
    local:         local,
    data_previsao: dataPrev || null,
    numero_os:     numeroOs  || null,
    link_os:       linkOsRaw || null
  });

  if (result.success) {
    activeFrotaSubTab = 'retidos';
    showToast(`🔒 Retenção ${result.retencao.numero_retencao} (${result.retencao.placa}) registrada com sucesso!`, 'warning');
    renderApp();
  } else {
    alert('❌ Erro ao registrar retenção. Tente novamente.');
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// BUSCA INTELIGENTE DE VEÍCULO (dropdown filtrado por qualquer sequência)
// ─────────────────────────────────────────────────────────────────────────────

/** Filtra a lista de veículos por qualquer sequência e exibe dropdown. */
function frtFiltrarVeiculos(query) {
  const dd = document.getElementById('frt-veiculo-dropdown');
  if (!dd) return;

  const veiculos = (db.data.veiculos || []).filter(v => v.situacao !== 'Inativo');
  const q = (query || '').toUpperCase().replace(/\s+/g, '');

  const filtrados = q.length === 0
    ? veiculos
    : veiculos.filter(v => {
        const placa  = (v.placa  || '').toUpperCase().replace(/\s+/g, '');
        const modelo = (v.tipo   || v.modelo || '').toUpperCase();
        return placa.includes(q) || modelo.includes(q);
      });

  const esc = s => s.replace(/'/g, "\\'");

  if (filtrados.length === 0) {
    dd.innerHTML = `<div class="px-4 py-3 text-xs text-slate-500 text-center">Nenhum veículo encontrado</div>`;
  } else {
    const hi = (txt) => {
      if (!q) return txt;
      const re = new RegExp(q.replace(/[-[\]{}()*+?.,\\^$|#\s]/g, '\\$&'), 'gi');
      return txt.replace(re, m => `<mark class="bg-amber-400/30 text-amber-300 rounded px-0.5">${m}</mark>`);
    };
    dd.innerHTML = filtrados.map(v => {
      const descr = v.tipo || v.modelo || '';
      const label = v.placa + (descr ? ' — ' + descr : '');
      return `<button type="button"
        onclick="frtSelecionarVeiculo(${v.id},'${esc(v.placa)}','${esc(descr)}','${esc(label)}')"
        class="w-full text-left px-4 py-2.5 text-sm hover:bg-slate-700 transition flex items-center gap-3">
        <span class="font-black text-white tracking-widest text-xs font-mono">${hi(v.placa)}</span>
        <span class="text-slate-400 text-xs">${hi(descr)}</span>
      </button>`;
    }).join('');
  }

  dd.classList.remove('hidden');
}

/** Seleciona um veículo do dropdown e preenche os campos ocultos. */
function frtSelecionarVeiculo(id, placa, tipo, labelCompleto) {
  document.getElementById('frt-veiculo-id').value   = id;
  document.getElementById('frt-placa-hidden').value = placa;
  document.getElementById('frt-tipo-hidden').value  = tipo;
  const busca = document.getElementById('frt-veiculo-busca');
  if (busca) { busca.value = ''; busca.blur(); }
  const badge = document.getElementById('frt-veiculo-badge');
  const txt   = document.getElementById('frt-veiculo-badge-txt');
  if (badge && txt) {
    txt.textContent = '✅ ' + labelCompleto;
    badge.classList.remove('hidden');
    badge.classList.add('flex');
  }
  frtFecharDropdown();
}

/** Fecha o dropdown de veículos. */
function frtFecharDropdown() {
  const dd = document.getElementById('frt-veiculo-dropdown');
  if (dd) dd.classList.add('hidden');
}

/** Limpa a seleção de veículo e permite nova busca. */
function frtLimparVeiculo() {
  document.getElementById('frt-veiculo-id').value   = '';
  document.getElementById('frt-placa-hidden').value = '';
  document.getElementById('frt-tipo-hidden').value  = '';
  const badge = document.getElementById('frt-veiculo-badge');
  if (badge) { badge.classList.add('hidden'); badge.classList.remove('flex'); }
  const busca = document.getElementById('frt-veiculo-busca');
  if (busca) { busca.value = ''; busca.focus(); }
}

/** 3C-action: Abre o modal de liberação para o registro indicado. */
function abrirModalLiberacao(id) {
  window._frotaLiberacaoId = id;
  const modal = document.getElementById('modal-liberacao-frota');
  if (modal) {
    modal.classList.remove('hidden');
    modal.classList.add('flex');
  }
  const acaoEl = document.getElementById('modal-acao-liberacao-frota');
  if (acaoEl) acaoEl.value = '';
}

/** Fecha o modal de liberação. */
/** Fecha o modal de liberação. */
function fecharModalLiberacao() {
  const modal = document.getElementById('modal-liberacao-frota');
  if (modal) {
    modal.classList.add('hidden');
    modal.classList.remove('flex');
  }
  window._frotaLiberacaoId = null;
}

