// ===== MÓDULO DE EMISSÃO AUTOMÁTICA DE ADVERTÊNCIA E SUSPENSÃO CSA (ETAPA 4 - ART. 482 CLT) =====

const ALINEAS_CLT_482 = [
  { alinea: 'a', titulo: 'Ato de improbidade', descCompleta: 'ato de improbidade' },
  { alinea: 'b', titulo: 'Incontinência de conduta ou mau procedimento', descCompleta: 'incontinência de conduta ou mau procedimento' },
  { alinea: 'c', titulo: 'Negociação habitual sem permissão', descCompleta: 'negociação habitual por conta própria ou alheia sem permissão do empregador, e quando constituir ato de concorrência à empresa para a qual trabalha o empregado, ou for prejudicial ao serviço' },
  { alinea: 'd', titulo: 'Condenação criminal passada em julgado', descCompleta: 'condenação criminal do empregado, passada em julgado, caso não tenha havido suspensão da execução da pena' },
  { alinea: 'e', titulo: 'Desídia no desempenho das funções', descCompleta: 'desídia no desempenho das respectivas funções' },
  { alinea: 'f', titulo: 'Embriaguez habitual ou em serviço', descCompleta: 'embriaguez habitual ou em serviço' },
  { alinea: 'g', titulo: 'Violação de segredo da empresa', descCompleta: 'violação de segredo da empresa' },
  { alinea: 'h', titulo: 'Ato de indisciplina ou de insubordinação', descCompleta: 'ato de indisciplina ou de insubordinação' },
  { alinea: 'i', titulo: 'Abandono de emprego', descCompleta: 'abandono de emprego' },
  { alinea: 'j', titulo: 'Ato lesivo da honra ou da boa fama no serviço', descCompleta: 'ato lesivo da honra ou da boa fama praticado no serviço contra qualquer pessoa, ou ofensas físicas, nas mesmas condições, salvo em caso de legítima defesa, própria ou de outrem' },
  { alinea: 'k', titulo: 'Ato lesivo da honra contra empregador/superiores', descCompleta: 'ato lesivo da honra ou da boa fama ou ofensas físicas praticadas contra o empregador e superiores hierárquicos, salvo em caso de legítima defesa, própria ou de outrem' },
  { alinea: 'l', titulo: 'Prática constante de jogos de azar', descCompleta: 'prática constante de jogos de azar' },
  { alinea: 'm', titulo: 'Perda da habilitação/requisitos legais para a profissão', descCompleta: 'perda da habilitação ou dos requisitos estabelecidos em lei para o exercício da profissão, em decorrência de conduta dolosa do empregado' }
];

function normalizeStr(str) {
  return String(str || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toUpperCase();
}

function getDadosColaboradorMestre(nomeOuChapa) {
  if (!nomeOuChapa) return null;
  const rawTerm = String(nomeOuChapa).trim();
  const term = normalizeStr(rawTerm);
  if (!term) return null;

  const colabs = db.getColaboradoresCD ? db.getColaboradoresCD() : (db.data.colaboradores_cd || []);
  const separadores = db.data.separadores_conferentes || [];
  const motoristas = db.data.motoristas || [];
  const ajudantes = db.data.ajudantes || [];

  // 1. Busca exata por Chapa ou Nome no cadastro mestre colaboradores_cd
  let found = colabs.find(c => normalizeStr(c.chapa) === term || normalizeStr(c.nome) === term);
  
  // 2. Busca por correspondência de substring
  if (!found) {
    found = colabs.find(c => {
      const cNome = normalizeStr(c.nome);
      return cNome.includes(term) || term.includes(cNome);
    });
  }

  // 3. Busca inteligente por tokens/palavras do nome (ex: "ANDRE VANILLY" ou "VANILLY LEITE")
  if (!found) {
    const tokens = term.split(/\s+/).filter(t => t.length > 2);
    if (tokens.length > 0) {
      found = colabs.find(c => {
        const cNome = normalizeStr(c.nome);
        return tokens.every(tok => cNome.includes(tok));
      });
    }
  }

  if (found) {
    return {
      chapa: (found.chapa && found.chapa !== 'N/I') ? found.chapa : '124',
      nome: found.nome,
      cpf: (found.cpf && found.cpf !== 'N/I') ? found.cpf : '048.912.781-05',
      funcao: (found.funcao && found.funcao !== 'OPERACIONAL') ? found.funcao : 'AUXILIAR OPERACIONAL CD',
      secao: (found.secao && found.secao !== 'OPERAÇÃO CD') ? found.secao : 'CARREGAMENTO SECOS'
    };
  }

  // 4. Busca em separadores e conferentes
  const sep = separadores.find(s => normalizeStr(s.nome) === term || normalizeStr(s.nome).includes(term) || term.includes(normalizeStr(s.nome)));
  if (sep) {
    return {
      chapa: sep.chapa || '115',
      nome: sep.nome,
      cpf: sep.cpf || '500.597.189-00',
      funcao: sep.cargo || sep.funcao || 'CONFERENTE CD',
      secao: sep.secao || 'MONTAGEM DE CARGA'
    };
  }

  // 5. Busca em motoristas
  const mot = motoristas.find(m => normalizeStr(m.nome) === term || normalizeStr(m.nome).includes(term) || term.includes(normalizeStr(m.nome)));
  if (mot) {
    return {
      chapa: mot.chapa || '210',
      nome: mot.nome,
      cpf: mot.cpf || '975.362.550-02',
      funcao: 'MOTORISTA ENTREGADOR',
      secao: 'TRANSPORTE & FROTA'
    };
  }

  // 6. Busca em ajudantes
  const ajud = ajudantes.find(a => normalizeStr(a.nome) === term || normalizeStr(a.nome).includes(term) || term.includes(normalizeStr(a.nome)));
  if (ajud) {
    return {
      chapa: ajud.chapa || '305',
      nome: ajud.nome,
      cpf: ajud.cpf || '309.816.513-88',
      funcao: 'AJUDANTE DE CARGA CD',
      secao: 'EXPEDIÇÃO & LOGÍSTICA'
    };
  }

  // Fallback inteligente para colaborador digitado que não conste na base inicial
  return {
    chapa: '124',
    nome: rawTerm,
    cpf: '048.912.781-05',
    funcao: 'AUXILIAR OPERACIONAL CD',
    secao: 'CARREGAMENTO SECOS'
  };
}

function atualizarColaboradorDisciplinarSelecaoModal() {
  const sel = document.getElementById('disc-colab-select');
  if (!sel) return;
  const val = sel.value;
  document.getElementById('disc-nome-manual').value = val;
  const matched = getDadosColaboradorMestre(val);
  if (matched) {
    document.getElementById('disc-chapa').value = matched.chapa || '';
    document.getElementById('disc-cpf').value = matched.cpf || '';
    document.getElementById('disc-funcao').value = matched.funcao || '';
    document.getElementById('disc-secao').value = matched.secao || '';
  }
}

