async function handleConfirmarEmissaoDisciplinar(e) {
  e.preventDefault();
  const tipo = document.getElementById('disc-tipo')?.value || 'ADVERTENCIA';
  const gerarPdf = (document.getElementById('disc-gerar-pdf')?.value || 'true') === 'true';
  const selectElem = document.getElementById('disc-colab-select');
  const nome = (selectElem?.value || document.getElementById('disc-nome-manual')?.value || '').trim().toUpperCase();
  
  // Captura alíneas selecionadas (multi-opção). Para Orientação Verbal, as
  // alíneas do Art. 482 CLT são opcionais — nem toda orientação verbal está
  // ligada a uma hipótese de justa causa.
  const checkedBoxes = document.querySelectorAll('input[name="disc-alinea-check"]:checked');
  const alineasSelecionadasKeys = Array.from(checkedBoxes).map(cb => cb.value);

  if (tipo !== 'ORIENTACAO_VERBAL' && alineasSelecionadasKeys.length === 0) {
    alert('Selecione pelo menos uma alínea do Artigo 482 da CLT.');
    return;
  }

  // Busca dados mestre do colaborador para a impressão
  const colabMatched = getDadosColaboradorMestre(nome);
  const chapa = colabMatched ? colabMatched.chapa : (document.getElementById('disc-chapa')?.value || 'N/I');
  const cpf = colabMatched ? colabMatched.cpf : (document.getElementById('disc-cpf')?.value || 'N/I');
  const funcao = colabMatched ? colabMatched.funcao : (document.getElementById('disc-funcao')?.value || 'OPERACIONAL CD');
  const secao = colabMatched ? colabMatched.secao : (document.getElementById('disc-secao')?.value || 'CARREGAMENTO CD');

  const diasSuspensao = parseInt(document.getElementById('disc-dias')?.value || '1', 10);
  const dataOc = document.getElementById('disc-data')?.value || agoraIsoBrasilia().slice(0,10);
  const gestor = (document.getElementById('disc-gestor')?.value || '').trim().toUpperCase();
  const motivo = (document.getElementById('disc-motivo')?.value || '').trim();

  const parentData = document.getElementById('disc-parent-data')?.value;
  const parentTurno = document.getElementById('disc-parent-turno')?.value;
  const parentType = document.getElementById('disc-parent-type')?.value;
  const parentIndexStr = document.getElementById('disc-parent-index')?.value;

  if (!nome || !motivo) {
    alert('Preencha o nome do colaborador e o detalhamento do motivo.');
    return;
  }

  // Mesma causa raiz do fix de importação de escala (21/08/2026): o número
  // sequencial (MD-xxxx) é gerado olhando só o estado LOCAL deste
  // aparelho. Sem puxar a nuvem antes, dois aparelhos desincronizados
  // podem gerar o MESMO número para medidas diferentes — e a coluna é
  // UNIQUE no banco, então uma delas nunca sincroniza (silenciosamente).
  // Feito antes de qualquer gravação local desta função (inclusive o
  // saveResumoDiarioCD logo abaixo) para não perder essa gravação caso o
  // pull da nuvem sobrescreva o estado local em seguida.
  if (window.cloudStore && window.cloudStore.isConfigured()) {
    try { await window.cloudStore.syncCloudToLocal(); } catch(errSync) {}
  }

  if (parentData && parentTurno && parentType && parentIndexStr !== '') {
    const parentIndex = parseInt(parentIndexStr, 10);
    const resumo = db.getResumoDiarioCD(parentData, parentTurno);
    let item = null;
    if (parentType === 'colaborador') item = resumo.ocorrencias_colaboradores?.[parentIndex];
    else if (parentType === 'operacional') item = resumo.ocorrencias?.[parentIndex];
    
    if (item) {
      item.medida_disciplinar = tipo;
      item.alinea_clt = alineasSelecionadasKeys.join(', ');
      if (tipo === 'SUSPENSAO') item.dias_suspensao = diasSuspensao;
      item.disciplinar_gerada_em = agoraIsoBrasilia();
      db.saveResumoDiarioCD(resumo);
    }
  }

  // Orientação Verbal não é mais uma medida administrativa (pedido de
  // 19/08/2026): passa a ser gravada em orientacoes_feedback — o mesmo
  // bloco "Orientação e Feedback" do Acompanhamento de Funcionário/Dossiê
  // Motorista — deixando medidas_disciplinares só com Advertência e
  // Suspensão. Fora isso, o fluxo de salvamento é idêntico (sempre grava,
  // venha a emissão de uma ocorrência do Resumo Diário CD ou avulsa).
  let resMedida;
  let jaTinhaAntes;
  if (tipo === 'ORIENTACAO_VERBAL') {
    jaTinhaAntes = db.getOrientacoesFeedback(nome).length;
    const resOrientacao = db.addOrientacaoFeedback({
      colaborador_tipo: 'CD',
      colaborador_id: colabMatched ? colabMatched.id : null,
      colaborador_nome: nome,
      data: dataOc,
      ocorrencia: motivo,
      acao: `ORIENTAÇÃO VERBAL APLICADA${gestor ? ` — GESTOR: ${gestor}` : ''}`
    });
    resMedida = { success: resOrientacao.success, message: resOrientacao.message };
  } else {
    jaTinhaAntes = db.contarReincidencia(nome, tipo);
    resMedida = db.registrarMedidaDisciplinar({
      tipo,
      colaborador_tipo: 'CD',
      colaborador_id: colabMatched ? colabMatched.id : null,
      colaborador_nome: nome,
      chapa, cpf, funcao, secao,
      alineas_clt: alineasSelecionadasKeys.join(', '),
      dias_suspensao: diasSuspensao,
      motivo,
      gestor,
      data_ocorrencia: dataOc
    });
  }

  fecharModalResumo();

  if (!resMedida.success) {
    showToast(resMedida.message, 'error');
  } else if (jaTinhaAntes > 0) {
    showToast(`⚠️ Atenção: esta é a ${jaTinhaAntes + 1}ª medida do tipo "${tipo === 'SUSPENSAO' ? 'Suspensão' : tipo === 'ORIENTACAO_VERBAL' ? 'Orientação Verbal' : 'Advertência'}" para ${nome}.`, 'warning');
  }

  if (gerarPdf) {
    gerarPdfDisciplinarOficial({
      tipo,
      nome,
      chapa,
      cpf,
      funcao,
      secao,
      alineasKeys: alineasSelecionadasKeys,
      diasSuspensao,
      dataOc,
      gestor,
      motivo
    });
  }

  renderApp();
}

function gerarTermoAdvertenciaPdf(dados) {
  gerarPdfDisciplinarOficial({
    tipo: 'ADVERTENCIA',
    nome: dados.colab || '',
    funcao: dados.cargo || 'OPERACIONAL CD',
    dataOc: dados.dataOc || '',
    motivo: dados.motivo || '',
    alineasKeys: ['e']
  });
}

function gerarPdfDisciplinarOficial(dados) {
  const colabMestre = getDadosColaboradorMestre(dados.nome);
  const chapa = (dados.chapa && dados.chapa !== 'N/I') ? dados.chapa : (colabMestre?.chapa || '124');
  const cpf = (dados.cpf && dados.cpf !== 'N/I') ? dados.cpf : (colabMestre?.cpf || '048.912.781-05');
  const funcao = (dados.funcao && dados.funcao !== 'OPERACIONAL CD') ? dados.funcao : (colabMestre?.funcao || 'AUXILIAR OPERACIONAL CD');
  const secao = (dados.secao && dados.secao !== 'CARREGAMENTO CD') ? dados.secao : (colabMestre?.secao || 'CARREGAMENTO SECOS');

  const alineasKeys = Array.isArray(dados.alineasKeys) && dados.alineasKeys.length > 0 ? dados.alineasKeys : ['e'];
  const alineasObjetos = alineasKeys.map(k => ALINEAS_CLT_482.find(a => a.alinea === k) || ALINEAS_CLT_482[4]);

  const isSuspensao = dados.tipo === 'SUSPENSAO';
  const dias = dados.diasSuspensao || 1;

  const dtOc = dados.dataOc ? new Date(dados.dataOc + 'T12:00:00') : new Date();
  
  // 1. O afastamento começa no dia SEGUINTE ao dia aplicado (desconsidera o dia aplicado)
  let dtInicio = new Date(dtOc);
  dtInicio.setDate(dtInicio.getDate() + 1);
  if (dtInicio.getDay() === 0) { // Se o dia seguinte for domingo, pula para a segunda-feira
    dtInicio.setDate(dtInicio.getDate() + 1);
  }
  const dtInicioStr = dtInicio.toLocaleDateString('pt-BR');
  
  // 2. Calcula a data final do afastamento (contando a quantidade de dias de suspensão e desconsiderando domingos)
  let dtFim = new Date(dtInicio);
  let diasAdicionados = 1;
  while (diasAdicionados < dias) {
    dtFim.setDate(dtFim.getDate() + 1);
    if (dtFim.getDay() === 0) { // Desconsidera domingo no período
      dtFim.setDate(dtFim.getDate() + 1);
    }
    diasAdicionados++;
  }
  const dtFimStr = dtFim.toLocaleDateString('pt-BR');

  // 3. Calcula o dia de retorno obrigatório às atividades (dia seguinte ao término, desconsiderando domingos)
  let dtRetorno = new Date(dtFim);
  dtRetorno.setDate(dtRetorno.getDate() + 1);
  if (dtRetorno.getDay() === 0) { // Se o retorno cair no domingo, desconsidera e joga para segunda-feira
    dtRetorno.setDate(dtRetorno.getDate() + 1);
  }
  const dtRetornoStr = dtRetorno.toLocaleDateString('pt-BR');

  const win = window.open('', '_blank', 'width=950,height=950');
  if (!win) {
    alert('Bloqueador de pop-up ativado. Por favor, permita pop-ups para visualizar e imprimir o PDF.');
    return;
  }

  win.document.write(`
    <!DOCTYPE html>
    <html lang="pt-BR">
    <head>
      <meta charset="UTF-8">
      <title>${isSuspensao ? 'TERMO DE SUSPENSÃO DISCIPLINAR' : 'TERMO DE ADVERTÊNCIA DISCIPLINAR'} — CSA SERVICES LTDA</title>
      <style>
        @media print {
          @page { size: A4 portrait; margin: 10mm 14mm; }
          body { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
        }
        * { box-sizing: border-box; }
        body { font-family: Arial, Helvetica, sans-serif; padding: 4px 6px; color: #0f172a; background: #fff; line-height: 1.48; font-size: 11px; }
        
        .header { display: flex; align-items: center; justify-content: space-between; border-bottom: 2.5px solid #1e293b; padding-bottom: 8px; margin-bottom: 12px; }
        .logo-group { display: flex; align-items: center; gap: 12px; }
        .logo-img { height: 48px; max-width: 160px; object-fit: contain; }
        .company-name { font-size: 15px; font-weight: 900; color: #0f172a; text-transform: uppercase; letter-spacing: 0.5px; }
        .company-sub { font-size: 9px; color: #475569; font-weight: 700; }
        .company-cnpj { font-size: 9.5px; font-weight: 800; color: #1e293b; text-align: right; line-height: 1.35; }

        .doc-title { text-align: center; background: ${isSuspensao ? '#991b1b' : '#1e293b'}; color: #ffffff; padding: 7px 14px; font-size: 13.5px; font-weight: 900; letter-spacing: 1px; text-transform: uppercase; border-radius: 4px; margin-bottom: 12px; }
        
        .box-colab { border: 1.5px solid #cbd5e1; background: #ffffff; border-radius: 6px; padding: 9px 14px; margin-bottom: 12px; }
        .grid-colab { display: grid; grid-template-columns: 0.8fr 2fr 1.3fr; gap: 7px 14px; }
        .lbl { font-size: 8.5px; font-weight: 800; color: #475569; text-transform: uppercase; }
        .val { font-size: 11px; font-weight: 900; color: #0f172a; }

        .fatos-box { background: #f8fafc; border: 1.5px solid #cbd5e1; padding: 14px 16px; border-radius: 6px; min-height: 65px; display: flex; align-items: center; font-weight: 900; font-size: 11px; text-transform: uppercase; color: #0f172a; margin: 12px 0; text-align: justify; white-space: pre-wrap; line-height: 1.45; }
        
        .alineas-box { background: #f8fafc; border-left: 4px solid #334155; padding: 9px 14px; margin: 12px 0; font-size: 10.5px; border-radius: 4px; line-height: 1.45; }

        .suspensao-periodo { border: 1.5px solid #b91c1c; background: #fef2f2; padding: 9px 14px; border-radius: 6px; margin: 12px 0; text-align: center; }
        .suspensao-title { font-size: 11.5px; font-weight: 900; color: #991b1b; text-transform: uppercase; }
        .suspensao-dates { font-size: 11px; font-weight: 800; color: #1e293b; margin-top: 3px; }

        .p-text { margin: 11px 0; text-align: justify; font-size: 11px; line-height: 1.5; color: #0f172a; }

        .sigs-container { margin-top: 22px; margin-bottom: 12px; }
        .sigs-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 36px; text-align: center; }
        .sig-space-main { height: 45px; }
        .sig-line { border-top: 1.5px solid #0f172a; margin-bottom: 4px; }
        .sig-lbl { font-size: 9.5px; font-weight: 800; text-transform: uppercase; color: #0f172a; line-height: 1.35; }

        .recusa-box { margin-top: 14px; border: 1.2px dashed #64748b; background: #f8fafc; padding: 9px 14px; border-radius: 6px; }
        .recusa-title { font-size: 9.5px; font-weight: 900; color: #334155; text-transform: uppercase; text-align: center; margin-bottom: 4px; }
        .recusa-text { font-size: 9px; color: #475569; text-align: justify; margin-bottom: 6px; line-height: 1.35; }
        .sig-space-test { height: 40px; }
        .sig-line-test { border-top: 1.2px solid #0f172a; margin-bottom: 3px; }
        .sig-lbl-test { font-size: 9px; font-weight: 800; text-transform: uppercase; color: #0f172a; line-height: 1.3; }
      </style>
    </head>
    <body onload="window.print()">
      <!-- CABEÇALHO CORPORATIVO -->
      <div class="header">
        <div class="logo-group">
          <img src="documents/logo csa.png" alt="CSA SERVICES" class="logo-img" onerror="this.src='${LOGO_JR_VERDE_BASE64}'">
          <div>
            <div class="company-name">CSA SERVICES LTDA</div>
            <div class="company-sub">LOGÍSTICA INTEGRADA & OPERAÇÕES DE CENTRO DE DISTRIBUIÇÃO</div>
          </div>
        </div>
        <div class="company-cnpj">
          CNPJ: 50.699.226/0001-09<br>
          <span style="font-size:9px; font-weight:bold; color:#64748b;">Emissão: ${formatarData(new Date())}</span>
        </div>
      </div>

      <!-- TÍTULO DO DOCUMENTO -->
      <div class="doc-title">
        ${isSuspensao ? `TERMO DE SUSPENSÃO DISCIPLINAR (${dias} DIA${dias > 1 ? 'S' : ''})` : 'TERMO DE ADVERTÊNCIA DISCIPLINAR'}
      </div>

      <!-- QUADRO DO COLABORADOR -->
      <div class="box-colab">
        <div class="grid-colab">
          <div><div class="lbl">CHAPA</div><div class="val">${chapa}</div></div>
          <div><div class="lbl">NOME DO COLABORADOR</div><div class="val">${dados.nome}</div></div>
          <div><div class="lbl">CPF</div><div class="val">${cpf}</div></div>
          <div><div class="lbl">FUNÇÃO / CARGO</div><div class="val">${funcao}</div></div>
          <div><div class="lbl">SEÇÃO / SETOR</div><div class="val">${secao}</div></div>
          <div><div class="lbl">DATA DA OCORRÊNCIA</div><div class="val">${formatarData(dados.dataOc || new Date())}</div></div>
        </div>
      </div>

      <!-- CORPO DO RELATÓRIO JURÍDICO -->
      <p class="p-text">
        Foi apurado que, Vossa Senhoria cometeu uma falta considerada grave pela legislação, conforme descrito a seguir:
      </p>

      <!-- CAMPO DO RELATÓRIO DO MOTIVO (EXPANDIDO E COM PRESENÇA FORMAL) -->
      <div class="fatos-box">
${dados.motivo}
      </div>

      <p class="p-text">
        Tal falha contraria os procedimentos internos da empresa e compromete a eficiência das operações, além de causar prejuízos ao desempenho das atividades.
      </p>

      <p class="p-text">
        Este ocorrido é considerado falta grave conforme artigo 482 da CLT nas alínea(s) descrita(s) abaixo:
      </p>

      <!-- AS ALÍNEAS SELECIONADAS -->
      <div class="alineas-box">
        ${alineasObjetos.map(a => `
          <div style="margin: 3px 0; color: #0f172a; font-size: 10.5px;">
            <b>Alínea "${a.alinea.toUpperCase()}"</b> &nbsp;&nbsp; ${a.descCompleta}
          </div>
        `).join('')}
      </div>

      <p class="p-text">
        Na intenção de evitar a repetição desta conduta, decidimos lhe aplicar a pena de <b>${isSuspensao ? `SUSPENSÃO DISCIPLINAR PELO PERÍODO DE ${dias} DIA(S)` : 'ADVERTÊNCIA'}</b>.
      </p>

      ${isSuspensao ? `
      <!-- PERÍODO DE SUSPENSÃO -->
      <div class="suspensao-periodo">
        <div class="suspensao-title">⛔ DETALHES DO PERÍODO DE AFASTAMENTO / SUSPENSÃO DISCIPLINAR</div>
        <div class="suspensao-dates">
          Afastamento de <b>${dtInicioStr}</b> a <b>${dtFimStr}</b> (${dias} dia${dias > 1 ? 's' : ''} de suspensão)<br>
          <span style="color:#991b1b;">Retorno obrigatório às atividades em: <b>${dtRetornoStr}</b></span>
        </div>
        <div style="font-size:9.5px; color:#64748b; margin-top:3px;">
          Durante o período de suspensão disciplinar, haverá o devido prejuízo salarial e contagem nos dias de afastamento conforme prevê a legislação trabalhista vigente.
        </div>
      </div>` : ''}

      <p class="p-text" style="margin-top: 11px; margin-bottom: 14px;">
        Esclarecemos que a reincidência em tal atitude poderá ensejar uma suspensão disciplinar ou até mesmo extinção do contrato de trabalho por justa causa. Assim, evite a reincidência da prática de seu ato, o que, se ocorrer, nos obrigará a tomar outras medidas cabíveis de acordo com a legislação em vigor.
      </p>

      <!-- ASSINATURAS PRINCIPAIS -->
      <div class="sigs-container">
        <div class="sigs-grid">
          <div>
            <div class="sig-space-main"></div>
            <div class="sig-line"></div>
            <div class="sig-lbl">CSA SERVICES LTDA<br><span style="font-size:9px; color:#475569;">${dados.gestor || 'SUPERVISÃO CD / RECURSOS HUMANOS'}</span></div>
          </div>
          <div>
            <div class="sig-space-main"></div>
            <div class="sig-line"></div>
            <div class="sig-lbl">${dados.nome}<br><span style="font-size:9px; color:#475569;">ASSINATURA DO EMPREGADO (CIENTE EM ___/___/____)</span></div>
          </div>
        </div>
      </div>

      <!-- TERMO DE RECUSA DE ASSINATURA (2 TESTEMUNHAS) -->
      <div class="recusa-box">
        <div class="recusa-title">📜 TERMO DE DECLARAÇÃO E RECUSA DE ASSINATURA DO EMPREGADO (2 TESTEMUNHAS)</div>
        <div class="recusa-text">
          Declaramos para os devidos fins que o colaborador acima identificado tomou conhecimento do presente Termo Disciplinar na data estipulada, porém <b>RECUSOU-SE</b> a apor sua assinatura. Em razão disso, o documento foi lido integralmente em sua presença pelas testemunhas abaixo qualificadas:
        </div>
        <div class="sigs-grid" style="margin-top:6px;">
          <div>
            <div class="sig-space-test"></div>
            <div class="sig-line-test"></div>
            <div class="sig-lbl-test">TESTEMUNHA 1<br><span style="font-size:8.5px; color:#475569;">NOME: ______________________ | CPF/RG: __________________</span></div>
          </div>
          <div>
            <div class="sig-space-test"></div>
            <div class="sig-line-test"></div>
            <div class="sig-lbl-test">TESTEMUNHA 2<br><span style="font-size:8.5px; color:#475569;">NOME: ______________________ | CPF/RG: __________________</span></div>
          </div>
        </div>
      </div>
    </body>
    </html>
  `);
  win.document.close();
}


